use super::{exact_map, require_bool, require_int, require_text};
use crate::program_module::runtime::foreign_process::value::{
    CLOSURE_SCHEMA_V15, CLOSURE_SCHEMA_V16, CLOSURE_SCHEMA_V17, CLOSURE_SCHEMA_V18,
    CLOSURE_SCHEMA_V19,
};
use crate::program_module::runtime::foreign_process::{
    MAX_EXTERNAL_RUNTIME_PROCESS_MEMORY_BYTES, MAX_NODE_TOTAL_PROCESSES,
};

pub(super) fn is_schema(schema: &str) -> bool {
    matches!(
        schema,
        CLOSURE_SCHEMA_V15
            | CLOSURE_SCHEMA_V16
            | CLOSURE_SCHEMA_V17
            | CLOSURE_SCHEMA_V18
            | CLOSURE_SCHEMA_V19
    )
}

pub(super) fn verify_closure(value: &Value, schema: &str) -> Result<()> {
    let has_root_binding = matches!(
        schema,
        CLOSURE_SCHEMA_V16 | CLOSURE_SCHEMA_V17 | CLOSURE_SCHEMA_V18 | CLOSURE_SCHEMA_V19
    );
    exact_map(
        value,
        if has_root_binding { 23 } else { 22 },
        "foreign-process closure",
    )?;
    require_int(
        value,
        "max_process_memory_bytes",
        MAX_EXTERNAL_RUNTIME_PROCESS_MEMORY_BYTES as i128,
    )?;
    require_int(
        value,
        "max_total_processes",
        MAX_NODE_TOTAL_PROCESSES as i128,
    )?;
    require_bool(value, "job_process_images_content_bound", true)?;
    if has_root_binding {
        require_text(
            value,
            "runtime_support_root_binding",
            "exact_materialized_directory",
        )?;
    }
    Ok(())
}

